"""Reference registry. Only entries with a verified flag were checked against Crossref or arXiv."""

CHECK = "Crossref 2026-11-17"
ARX = "arXiv abstract page 2026-11-17"
NONE = "not verified in build environment"


def R(title, authors, year, venue, doi=None, url=None, kind="foundational", verified=CHECK,
      objective="", method="", data="", findings="", limits=""):
    link = f"https://doi.org/{doi}" if doi else url
    return dict(title=title, authors=authors, year=year, venue=venue, doi=doi, url=link,
                kind=kind, verified=verified, objective=objective, method=method,
                data=data, findings=findings, limits=limits)


