def bibtex(key):
    r = REFS[key]
    ident = r["doi"] or r["url"]
    return (f"@misc{{{key},\n  title = {{{r['title']}}},\n  author = {{{r['authors']}}},\n  year = {{{r['year']}}},\n"
            f"  note = {{{r['venue']}}},\n  url = {{{ident if ident and ident.startswith('http') else 'https://doi.org/' + str(ident)}}}\n}}")
